import sys
from collections import deque, defaultdict

def parse_paper(line):
    if ':' not in line:
        return []
    authors_part = line[:line.index(':')]
    authors = [a.strip() for a in authors_part.split(',')]
    return authors

def main():
    data = sys.stdin.read().splitlines()
    tsc = int(data[0].strip())
    idx = 1

    for scenario in range(1, tsc + 1):
        parts = data[idx].split()
        P = int(parts[0])
        N = int(parts[1])
        idx += 1

        papers = []
        for _ in range(P):
            line = data[idx].strip()
            idx += 1
            authors = parse_paper(line)
            if authors:
                papers.append(authors)

        query_names = []
        for _ in range(N):
            name = data[idx].strip()
            idx += 1
            query_names.append(name)

        erdos = "Erdos, P."
        graph = defaultdict(set)

        for authors in papers:
            for i, a1 in enumerate(authors):
                for a2 in authors[i+1:]:
                    graph[a1].add(a2)
                    graph[a2].add(a1)

        erdos_numbers = {}
        if erdos in graph or erdos in [a for paper in papers for a in paper]:
            queue = deque()
            if erdos in graph:
                for neighbor in graph[erdos]:
                    erdos_numbers[neighbor] = 1
                    queue.append(neighbor)
            else:
                queue.append(erdos)

            erdos_numbers[erdos] = 0

            visited = set([erdos])
            while queue:
                current = queue.popleft()
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        erdos_numbers[neighbor] = erdos_numbers[current] + 1
                        queue.append(neighbor)

        print(f"Scenario {scenario}")
        for name in query_names:
            if name in erdos_numbers:
                print(f"{name} {erdos_numbers[name]}")
            else:
                print(f"{name} infinity")

if __name__ == "__main__":
    main()
